insert into public.distributions
  (id,temple_id,centre_id,individual_id,team_id,campaign_id,distributed_on,mode,lines,book_count,set_count,points,version,created_by,updated_by,created_at,updated_at)
select i.id,i.temple_id,i.centre_id,i.individual_id,i.team_id,c.id,i.distributed_on,'detailed',i.lines,i.book_count,i.set_count,i.points,1,
  '162092c8-9240-498c-9cd4-4644151ba118'::uuid,'162092c8-9240-498c-9cd4-4644151ba118'::uuid,i.created_at,i.updated_at
from incoming i
join public.campaigns c on c.fallback_year=i.report_year
on conflict (id) do nothing;

alter table public.centres enable trigger audit_centre;
alter table public.individuals enable trigger audit_individual;
alter table public.teams enable trigger audit_team;
alter table public.campaigns enable trigger audit_special;

-- Hard validation. Any mismatch aborts the whole transaction.
do $$
declare
  imported_rows bigint; imported_books bigint; imported_sets bigint; imported_points numeric;
begin
  select count(*),coalesce(sum(book_count),0),coalesce(sum(set_count),0),coalesce(sum(points),0)
    into imported_rows,imported_books,imported_sets,imported_points
